-- ES/DE/FR translations for all 5 Malaysia milestones.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase1', 'es', 'Fase 1 — empresas con una facturación superior a 100 millones de RM', 'Los mayores contribuyentes se convierten en el primer grupo obligatorio, estableciendo MyInvois como la plataforma nacional de compensación.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase1', 'de', 'Phase 1 — Unternehmen mit über 100 Millionen RM Umsatz', 'Die größten Steuerzahler werden die erste verpflichtende Gruppe und etablieren MyInvois als nationale Clearing-Plattform.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase1', 'fr', 'Phase 1 — entreprises dépassant 100 millions de RM de chiffre d''affaires', 'Les plus grands contribuables deviennent le premier groupe obligatoire, établissant MyInvois comme plateforme nationale de contrôle.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase2', 'es', 'Fase 2 — de 25 a 100 millones de RM', 'Las empresas medianas-grandes se incorporan al mandato.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase2', 'de', 'Phase 2 — 25 Millionen bis 100 Millionen RM', 'Mittelgroße bis große Unternehmen treten der Vorgabe bei.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase2', 'fr', 'Phase 2 — de 25 à 100 millions de RM', 'Les moyennes-grandes entreprises rejoignent l''obligation.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase3', 'es', 'Fase 3 — de 5 a 25 millones de RM', 'El mandato se extiende más abajo en la escala de facturación hacia las empresas medianas.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase3', 'de', 'Phase 3 — 5 Millionen bis 25 Millionen RM', 'Die Vorgabe erstreckt sich weiter die Umsatzskala hinunter auf mittelgroße Unternehmen.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase3', 'fr', 'Phase 3 — de 5 à 25 millions de RM', 'L''obligation s''étend plus bas dans l''échelle de chiffre d''affaires vers les entreprises de taille moyenne.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase4', 'es', 'MyInvois Fase 4 — facturación de 1 a 5 millones de RM', 'Las empresas con una facturación anual de entre 1 y 5 millones de RM entraron en el mandato, con un periodo de relajación (sin sanciones por errores de envío) ampliado hasta el 31 de diciembre de 2027.', '["Regístrese para acceder al portal o API de MyInvois con LHDN", "Determine su fase usando sus cuentas auditadas del ejercicio 2022 o su primera declaración de impuestos disponible", "Las facturas electrónicas individuales son obligatorias por encima de 10.000 RM — la facturación consolidada ya no está permitida para esos importes"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase4', 'de', 'MyInvois Phase 4 — Umsatz 1-5 Mio. RM', 'Unternehmen mit einem Jahresumsatz zwischen 1 und 5 Millionen RM traten der Vorgabe bei, mit einer bis zum 31. Dezember 2027 verlängerten Lockerungsphase (keine Sanktionen für Einreichungsfehler).', '["Registrieren Sie sich für den MyInvois-Portal- oder API-Zugang bei der LHDN", "Bestimmen Sie Ihre Phase anhand Ihrer geprüften Abschlüsse für das Geschäftsjahr 2022 oder Ihrer ersten verfügbaren Steuererklärung", "Einzelne E-Rechnungen sind ab 10.000 RM verpflichtend — konsolidierte Rechnungsstellung ist für solche Beträge nicht mehr zulässig"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-phase4', 'fr', 'MyInvois Phase 4 — chiffre d''affaires de 1 à 5 millions de RM', 'Les entreprises dont le chiffre d''affaires annuel se situe entre 1 et 5 millions de RM sont entrées dans l''obligation, avec une période d''assouplissement (aucune sanction pour erreurs de soumission) prolongée jusqu''au 31 décembre 2027.', '["Inscrivez-vous pour l''accès au portail ou à l''API MyInvois auprès de la LHDN", "Déterminez votre phase à l''aide de vos comptes audités de l''exercice 2022 ou de votre première déclaration fiscale disponible", "Les factures électroniques individuelles sont obligatoires au-delà de 10 000 RM — la facturation consolidée n''est plus autorisée pour ces montants"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-related', 'es', 'Empresas relacionadas/filiales de grupos con 1 millón+ RM', 'Las empresas con una facturación inferior a 1 millón de RM que son filiales o empresas relacionadas de un grupo con 1 millón+ RM deben cumplir igualmente, independientemente de su propia facturación individual.', '["Compruebe la estructura del grupo — el estatus de empresa relacionada puede activar el mandato incluso para entidades pequeñas", "Regístrese y pruebe la integración con MyInvois bien antes del plazo"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-related', 'de', 'Verbundene/Tochterunternehmen von Gruppen mit 1 Mio.+ RM', 'Unternehmen mit einem Umsatz unter 1 Million RM, die Tochter- oder verbundene Unternehmen einer Gruppe mit 1 Million+ RM sind, müssen sich unabhängig von ihrem eigenen individuellen Umsatz dennoch daran halten.', '["Prüfen Sie die Konzernstruktur — der Status als verbundenes Unternehmen kann die Vorgabe auch für kleine Einheiten auslösen", "Registrieren und testen Sie die MyInvois-Integration weit vor der Frist"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('my-related', 'fr', 'Entreprises liées/filiales de groupes à 1 million+ RM', 'Les entreprises dont le chiffre d''affaires est inférieur à 1 million de RM mais qui sont des filiales ou entreprises liées d''un groupe atteignant 1 million+ RM doivent tout de même se conformer, indépendamment de leur propre chiffre d''affaires individuel.', '["Vérifiez la structure du groupe — le statut d''entreprise liée peut déclencher l''obligation même pour de petites entités", "Inscrivez-vous et testez l''intégration MyInvois bien avant l''échéance"]');
